            try:
                start_time_dt = datetime.strptime(start_time, "%Y-%m-%dT%H:%M:%S")
            except ValueError:
                start_time_dt = datetime.strptime(start_time, "%Y-%m-%dT%H:%M")
else:
    start_time_dt = start_time

if start_time_dt.timestamp() < now.timestamp():
    print("00:00")
else:
    delta = start_time_dt - now
    hours, remainder = divmod(int(delta.total_seconds()), 3600)
