# Let's convert both to datetime objects with the same structure (year, month, day, hour, minute).

# If either is a date, convert to datetime at midnight
if type(start_time_dt) == "date":
    start_time_dt = datetime.combine(start_time_dt, datetime.strptime("00:00", "%H:%M").time())
if type(now) == "date":
    now = datetime.combine(now, datetime.strptime("00:00", "%H:%M").time())

# Now compare
if type(start_time_dt) == "datetime" and type(now) == "datetime":
    if (start_time_dt.year, start_time_dt.month, start_time_dt.day, start_time_dt.hour, start_time_dt.minute) < (now.year, now.month, now.day, now.hour, now.minute):
        print("00:00")
    else:
        delta = start_time_dt - now
        hours, remainder = divmod(int(delta.total_seconds()), 3600)
        minutes = remainder // 60
        print("{:02d}:{:02d}".format(hours, minutes))
else:
    raise ValueError("Could not convert start_time_dt and now to comparable datetime objects.")
